#include "CymbalEngine.h"
namespace cymbalforge {
ImpactControls CymbalParameters::snapshot() const noexcept { ImpactControls c; c.brightness=brightness.load(); c.decay=decay.load(); c.choke=choke.load(); c.complexity=complexity.load(); c.shimmer=shimmer.load(); c.noise=noise.load(); c.subLevel=subLevel.load(); c.subTune=subTune.load(); c.subDecay=subDecay.load(); c.subDelay=subDelay.load(); c.filterCutoff=filterCutoff.load(); c.filterResonance=filterResonance.load(); c.filterMode=filterMode.load(); c.modLfoRate=modLfoRate.load(); c.modLfoDepth=modLfoDepth.load(); c.modTarget=modTarget.load(); c.model=model.load(); c.modes=modes.load(); for(int i=0;i<4;++i) c.samples[(size_t)i]={sampleLevel[(size_t)i].load(),sampleTune[(size_t)i].load(),sampleAttack[(size_t)i].load(),sampleRelease[(size_t)i].load(),sampleDelay[(size_t)i].load(),sampleLfoRate[(size_t)i].load(),sampleLfoDepth[(size_t)i].load()}; return c; }
void CymbalEngine::prepare(double rate, int block) { formats.registerBasicFormats(); for(auto& impact:impacts) impact.prepare(rate); juce::dsp::ProcessSpec s{rate, (juce::uint32) block, 2}; reverb.prepare(s); }
void CymbalEngine::strike(float v, float p) { impacts[(size_t)nextImpactVoice].trigger(v,p,parameters.snapshot()); nextImpactVoice=(nextImpactVoice+1)%maxImpactVoices; }
bool CymbalEngine::loadSampleSlot(int slot,const juce::File& file) { auto reader=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(file)); if(!reader || !juce::isPositiveAndBelow(slot,4)) return false; auto sample=std::make_shared<ImpactSampleData>(); sample->audio.setSize(juce::jmin(2,(int)reader->numChannels),int(reader->lengthInSamples)); reader->read(&sample->audio,0,sample->audio.getNumSamples(),0,true,true); sample->sampleRate=reader->sampleRate; for(auto& impact:impacts) impact.setSample(slot,sample); sampleFiles[(size_t)slot]=file; return true; }
juce::File CymbalEngine::sampleFile(int slot) const { return juce::isPositiveAndBelow(slot,4)?sampleFiles[(size_t)slot]:juce::File{}; }
void CymbalEngine::render(juce::AudioBuffer<float>& buffer, int start, int count) { buffer.clear(start,count); auto gain=parameters.gain.load(); for(int i=0;i<count;++i) { std::array<float,2> dry{}; for(auto& impact:impacts){auto voice=impact.render();dry[0]+=voice[0];dry[1]+=voice[1];} buffer.setSample(0,start+i,dry[0]*gain); buffer.setSample(1,start+i,dry[1]*gain); } juce::dsp::AudioBlock<float> b(buffer); auto sub=b.getSubBlock((size_t)start,(size_t)count); juce::dsp::ProcessContextReplacing<float> c(sub); juce::dsp::Reverb::Parameters p; p.wetLevel=parameters.reverb.load()*0.35f; p.dryLevel=1.0f; p.roomSize=.55f; reverb.setParameters(p); reverb.process(c); }
}
